from people_a import cat

cat("beginning", "In the Beginning", "The first families in Genesis.", "creation-light", [
 dict(id="adam-eve", name="Adam & Eve", role="The first man and woman", art="eden",
  facts=["Made by God", "Lived in the Garden of Eden", "Parents of Cain, Abel and Seth"],
  cards=[
   ("Who they were", "God formed Adam from the dust and breathed life into him. Then He made Eve from Adam’s side as his partner. They lived in a perfect garden called Eden."),
   ("One rule", "They could eat from any tree except one — the tree of the knowledge of good and evil. A serpent convinced Eve that God was holding out on them. She ate, gave some to Adam, and he ate too."),
   ("Hiding", "Right away they felt shame and hid from God. God sent them out of the garden — but even then He made them clothes and promised that one day a child of Eve would crush the serpent."),
   ("Why it matters", "Their choice is why the world is broken. God’s promise to them is the first hint of Jesus."),
  ], read=[("Genesis",2,"Adam and Eve are made"),("Genesis",3,"The fall")]),
 dict(id="cain-abel", name="Cain & Abel", role="The first brothers — and the first murder", art="cain-abel",
  facts=["Sons of Adam & Eve", "A farmer and a shepherd", "Jealousy turned deadly"],
  cards=[
   ("Who they were", "Cain grew crops and his younger brother Abel raised sheep. Both brought offerings to God."),
   ("Jealous", "God accepted Abel’s offering but not Cain’s. Cain got furious. God warned him: “Sin is crouching at your door — you must master it.”"),
   ("The murder", "Cain lured Abel into a field and killed him. God asked, “Where is your brother?” Cain said, “I don’t know. Am I my brother’s keeper?”"),
   ("Why it matters", "Even after this, God put a mark on Cain to protect him. God punishes sin but still shows mercy."),
  ], read=[("Genesis",4,"Cain and Abel")]),
 dict(id="noah", name="Noah", role="The man who built the ark", art="flood",
  facts=["Built a giant boat", "Rain for 40 days", "God’s rainbow promise"],
  cards=[
   ("Who he was", "The world had become violent and evil, but Noah walked with God."),
   ("The ark", "God told Noah to build a huge wooden boat, the ark, and fill it with his family and two of every kind of animal. Noah did everything God said."),
   ("The flood", "It rained for 40 days and nights and water covered the earth. Months later Noah sent out a dove, and it came back with an olive leaf — the water was going down."),
   ("The rainbow", "When they came out, God promised never to flood the whole earth again, and He put a rainbow in the sky as a sign."),
  ], read=[("Genesis",6,"Build an ark"),("Genesis",7,"The flood"),("Genesis",9,"The rainbow")]),
 dict(id="abraham", name="Abraham", role="Father of faith", art="three-angels",
  facts=["Left home at 75", "Had a son at 100", "Father of many nations"],
  cards=[
   ("Who he was", "Abram lived in a city called Ur. When he was 75, God told him to leave everything and go to a land He would show him. God promised to make his family a great nation and bless the whole world through it."),
   ("Waiting", "Abraham and his wife Sarah waited 25 years for the son God promised. God renamed him Abraham, “father of many.” Finally, at 100, he had Isaac."),
   ("The hardest test", "God asked Abraham to offer Isaac as a sacrifice. Abraham went, trusting God. At the last second an angel stopped him, and God provided a ram instead."),
   ("Why it matters", "Jews, Christians and Muslims all look back to Abraham. The Bible says he “believed God, and it was counted to him as righteousness.”"),
  ], read=[("Genesis",12,"God calls Abram"),("Genesis",15,"Count the stars"),("Genesis",22,"Abraham and Isaac")]),
 dict(id="sarah", name="Sarah", role="The woman who laughed — and then had a baby at 90", art="three-angels",
  facts=["Abraham’s wife", "Mother of Isaac", "Name means “princess”"],
  cards=[
   ("Who she was", "Sarah was Abraham’s wife. For decades she couldn’t have children."),
   ("Taking things into her own hands", "Tired of waiting, Sarah gave her servant Hagar to Abraham to have a child for her. It caused years of jealousy and pain."),
   ("She laughed", "When she was about 90, she overheard a visitor tell Abraham she would have a son within a year. She laughed to herself. The Lord asked, “Is anything too hard for the Lord?”"),
   ("Isaac", "A year later she had a son and named him Isaac, which means “laughter.”"),
  ], read=[("Genesis",18,"Sarah laughs"),("Genesis",21,"Isaac is born")]),
 dict(id="jacob", name="Jacob", role="The schemer God renamed Israel", art="jacob-wrestles",
  facts=["Twin of Esau", "Father of 12 sons", "The 12 tribes come from him"],
  cards=[
   ("Who he was", "Jacob was Isaac’s son and the younger twin of Esau. His name roughly means “he grabs” — he was born holding Esau’s heel."),
   ("Tricks", "He traded hungry Esau a bowl of stew for his rights as firstborn, then disguised himself to trick his blind father into giving him Esau’s blessing. Esau wanted to kill him, so Jacob ran."),
   ("The ladder", "Sleeping on a rock, Jacob dreamed of a stairway to heaven with angels going up and down. God promised to be with him wherever he went."),
   ("The wrestling match", "Years later, scared to face Esau, Jacob wrestled all night with a mysterious man. He wouldn’t let go until he got a blessing. God renamed him Israel — “he struggles with God.”"),
   ("Why it matters", "His 12 sons became the 12 tribes of Israel. God used a flawed man to build His people."),
  ], read=[("Genesis",27,"The stolen blessing"),("Genesis",28,"Jacob’s ladder"),("Genesis",32,"Wrestling God"),("Genesis",33,"Meeting Esau")]),
 dict(id="joseph-egypt", name="Joseph", role="Sold as a slave, became ruler of Egypt", art="joseph-reveals",
  facts=["Favorite son of Jacob", "The colorful coat", "Interpreted dreams"],
  cards=[
   ("Who he was", "Joseph was his father Jacob’s favorite son and got a special colorful coat. He also dreamed his brothers would bow to him. They hated him for it."),
   ("Sold", "His brothers threw him in a pit and sold him to traders for 20 pieces of silver. They told their father a wild animal killed him."),
   ("Prison to palace", "In Egypt, Joseph was falsely accused and thrown in prison. There God helped him explain dreams. When Pharaoh had dreams nobody understood, Joseph explained them: seven good years, then seven years of famine. Pharaoh put him in charge of all Egypt."),
   ("“I am Joseph”", "When the famine came, his brothers came to buy food and bowed down — not recognizing him. Joseph finally broke down crying and told them who he was."),
   ("Why it matters", "Joseph told them: “You meant it for evil, but God meant it for good.”"),
  ], read=[("Genesis",37,"Sold by his brothers"),("Genesis",41,"Pharaoh’s dreams"),("Genesis",45,"“I am Joseph”"),("Genesis",50,"“God meant it for good”")]),
])

cat("exodus", "Moses & the Promised Land", "Out of slavery and into the land God promised.", "red-sea", [
 dict(id="moses", name="Moses", role="The reluctant leader who led Israel out of Egypt", art="sinai",
  facts=["Raised in Pharaoh’s palace", "The burning bush", "Received the 10 Commandments"],
  cards=[
   ("Who he was", "Moses was born when Pharaoh ordered every Hebrew baby boy killed. His mother hid him in a basket in the Nile, and Pharaoh’s own daughter found him and raised him as a prince."),
   ("On the run", "As a grown man he killed an Egyptian who was beating a Hebrew slave, then fled to the desert and became a shepherd for 40 years."),
   ("The burning bush", "God spoke to him from a bush that was on fire but didn’t burn up: “Go tell Pharaoh, ‘Let my people go.’” Moses gave excuse after excuse. God went with him anyway."),
   ("Out of Egypt", "After ten plagues, Pharaoh let the Israelites go — then chased them. God split the Red Sea, they walked through on dry ground, and the water crashed back on the army."),
   ("The law", "On Mount Sinai God gave Moses the Ten Commandments. Moses led the people through the desert for 40 years."),
   ("How it ended", "Moses saw the Promised Land from a mountaintop but died before entering. The Bible says no prophet ever knew God face to face like Moses did."),
  ], read=[("Exodus",2,"Baby in a basket"),("Exodus",3,"The burning bush"),("Exodus",14,"The Red Sea"),("Exodus",20,"The 10 Commandments"),("Deuteronomy",34,"Moses dies")]),
 dict(id="aaron", name="Aaron", role="Moses’ brother and Israel’s first high priest", art="let-my-people-go",
  facts=["Moses’ older brother", "Spoke for Moses", "Made the golden calf"],
  cards=[
   ("Who he was", "Aaron was Moses’ older brother. Moses said he wasn’t a good speaker, so God sent Aaron to speak for him in front of Pharaoh."),
   ("The golden calf", "When Moses was on the mountain for 40 days, the people got impatient. Aaron collected their gold and made a calf idol. Moses came down and was furious."),
   ("High priest", "God still chose Aaron and his sons to be Israel’s priests. Aaron spoke the blessing still used today: “The Lord bless you and keep you…”"),
  ], read=[("Exodus",4,"Aaron speaks for Moses"),("Exodus",32,"The golden calf"),("Numbers",6,"The priestly blessing")]),
 dict(id="miriam", name="Miriam", role="Prophet, songwriter and big sister", art="moses-nile",
  facts=["Sister of Moses & Aaron", "Watched over baby Moses", "Led the women in song"],
  cards=[
   ("Who she was", "Miriam was Moses’ big sister. When baby Moses was floating in the Nile, she watched from the reeds — and cleverly offered to find a Hebrew nurse for Pharaoh’s daughter: their own mother."),
   ("The song", "After the Red Sea, Miriam grabbed a tambourine and led all the women in dancing and singing: “Sing to the Lord, for He has triumphed!”"),
   ("Why it matters", "The Bible calls her a prophet — one of the first women given that title."),
  ], read=[("Exodus",2,"Watching over Moses"),("Exodus",15,"Miriam’s song")]),
 dict(id="joshua", name="Joshua", role="The general who led Israel into the Promised Land", art="jericho",
  facts=["Moses’ assistant", "One of the 12 spies", "Jericho’s walls fell"],
  cards=[
   ("Who he was", "Joshua was Moses’ right-hand man. He was one of 12 spies sent into Canaan — and one of only two who said, “We can do this with God’s help.”"),
   ("Be strong and courageous", "When Moses died, God told Joshua, “Be strong and courageous. Don’t be afraid, for I am with you wherever you go.”"),
   ("Jericho", "God told Israel to march around Jericho once a day for six days, then seven times on the seventh day, then shout. They did — and the walls fell flat."),
   ("His choice", "At the end of his life, Joshua told Israel: “Choose today whom you will serve. As for me and my house, we will serve the Lord.”"),
  ], read=[("Joshua",1,"Be strong and courageous"),("Joshua",6,"Jericho"),("Joshua",24,"“As for me and my house”")]),
 dict(id="caleb", name="Caleb", role="The spy who still wanted a mountain at 85", art=None,
  facts=["One of the 12 spies", "Believed God", "Fought giants at 85"],
  cards=[
   ("Who he was", "Caleb and Joshua were the two spies who trusted God when the other ten said the giants in Canaan were too big."),
   ("40 years later", "Because the people sided with the ten, Israel wandered 40 years. But God promised Caleb a piece of the land."),
   ("Give me this mountain", "At 85, Caleb said, “I’m as strong today as I was then. Give me the hill country” — where the giants lived. And he took it."),
  ], read=[("Numbers",13,"The spies"),("Joshua",14,"“Give me this mountain”")]),
 dict(id="rahab", name="Rahab", role="The outsider who hid the spies", art=None,
  facts=["Lived in Jericho’s wall", "Hid two Israelite spies", "Ancestor of Jesus"],
  cards=[
   ("Who she was", "Rahab was a prostitute who lived in a house built into Jericho’s city wall."),
   ("Brave choice", "She hid two Israelite spies on her roof and lied to the king’s men to protect them. She said, “I know the Lord has given you this land.”"),
   ("The red rope", "The spies told her to hang a red cord from her window. When the walls fell, her family was saved."),
   ("Why it matters", "Rahab married into Israel and became the great-great-grandmother of King David — and an ancestor of Jesus."),
  ], read=[("Joshua",2,"Rahab hides the spies"),("Joshua",6,"Rahab is saved")]),
])
